pthread_key_t tsd_key;

void key_destructor(void *data_ptr) {
    if (data_ptr) {
        free(data_ptr);
    }
}

// Create the key, assigning the destructor
int status = pthread_key_create(
    &tsd_key,
    key_destructor
);

// Store thread-specific data (TSD)
char *buf = malloc(100);
pthread_setspecific(tsd_key, buf);

// Retrieve TSD
char *my_data = pthread_getspecific(tsd_key);

// Key must be destroyed when no longer needed
pthread_key_delete(tsd_key);
